INSERT INTO "Habilidade" ("id", "codigo", "nome", "descricao", "classe", "tipo", "elemento", "icone", "custo", "cooldown", "dano", "alcance", "raio", "duracao", "efeito", "potencia", "nivelReq", "ultimate", "aprendizado", "atualizadoEm") VALUES
('hab_carta_cortante', 'carta_cortante', 'Carta Cortante', 'Lança a carta da vez em linha reta. É o seu golpe básico: gasta uma carta e puxa outra.', 'CARTOMANTE', 'SKILLSHOT', 'ARCANO', 'minecraft:paper', 10, 2.5, 6, 16, 0, 0, '', 0, 1, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_embaralhar', 'embaralhar', 'Embaralhar', 'Troca a mão inteira por três cartas novas. Para quando a sorte não ajuda.', 'CARTOMANTE', 'BUFF', 'ARCANO', 'minecraft:book', 8, 10, 0, 0, 0, 0, 'frx:carta_embaralhar', 0, 2, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_cara_ou_coroa', 'cara_ou_coroa', 'Cara ou Coroa', 'Joga a moeda no alvo. Cara: o golpe sai em dobro. Coroa: sai pela metade e fere você um pouco, mas você fica mais forte e veloz por 6 s.', 'CARTOMANTE', 'ALVO', 'ARCANO', 'minecraft:gold_nugget', 20, 8, 9, 12, 0, 0, 'frx:carta_moeda', 0, 4, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_leque_de_cartas', 'leque_de_cartas', 'Leque de Cartas', 'Abre o baralho em leque à sua frente: fere, deixa lento e empurra todos. Gasta a carta da vez.', 'CARTOMANTE', 'AREA', 'ARCANO', 'minecraft:feather', 20, 7, 6, 7, 0, 0, 'frx:leque', 0, 5, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_truque_de_mao', 'truque_de_mao', 'Truque de Mão', 'Some numa nuvem de cartas e reaparece onde você mira, a até 10 blocos. Não gasta carta.', 'CARTOMANTE', 'MOBILIDADE', 'ARCANO', 'minecraft:ender_pearl', 20, 10, 0, 10, 0, 0, '', 0, 7, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_carta_marcada', 'carta_marcada', 'Carta Marcada', 'Crava uma carta no alvo, que continua ferindo por 5 s: metade do dano a cada segundo.', 'CARTOMANTE', 'ALVO', 'SOMBRA', 'minecraft:name_tag', 20, 10, 5, 16, 0, 5, 'frx:sangria', 0, 8, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_mare_de_sorte', 'mare_de_sorte', 'Maré de Sorte', 'Por 8 s o Coringa aparece muito mais: 35% de chance em cada carta nova, em vez de 8%.', 'CARTOMANTE', 'BUFF', 'SAGRADO', 'minecraft:rabbit_foot', 25, 25, 0, 0, 0, 8, 'frx:carta_sorte', 0, 10, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_mao_cheia', 'mao_cheia', 'Mão Cheia', 'Joga as três cartas da mão de uma vez, cada uma num inimigo à frente e com o seu naipe. Com um inimigo só, as três vão nele. A mão volta nova.', 'CARTOMANTE', 'SKILLSHOT', 'ARCANO', 'minecraft:filled_map', 30, 12, 7, 16, 0, 0, 'frx:carta_mao', 0, 12, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_cartas_na_mesa', 'cartas_na_mesa', 'Cartas na Mesa', 'Espalha o baralho no chão a até 12 blocos: fere todos num círculo de 4 blocos. Gasta a carta da vez, e o naipe vale para todos os atingidos.', 'CARTOMANTE', 'AREA', 'ARCANO', 'minecraft:map', 30, 12, 8, 12, 4, 0, '', 0, 14, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_blefe', 'blefe', 'Blefe', 'Finge fraqueza por 3 s: 60% do dano que você receber volta em quem atacou.', 'CARTOMANTE', 'BUFF', 'ARCANO', 'minecraft:carved_pumpkin', 20, 16, 0, 0, 0, 3, 'frx:refletir', 6, 16, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_as_na_manga', 'as_na_manga', 'Ás na Manga', 'A carta guardada para o fim: quanto menos vida o alvo tem, mais forte (até o triplo). Se matar, a recarga zera. Aprendida com um Tomo Arcano.', 'CARTOMANTE', 'ALVO', 'ARCANO', 'minecraft:nether_star', 30, 14, 9, 12, 0, 0, 'frx:executar', 0, 18, false, 'ITEM', CURRENT_TIMESTAMP),
('hab_casa_cheia', 'casa_cheia', 'Casa Cheia', 'O baralho inteiro cai ao seu redor. Todos os inimigos a até 7 blocos sofrem os quatro naipes de uma vez: 40% a mais de dano, ficam presos, e você se cura e recupera mana.', 'CARTOMANTE', 'AREA', 'ARCANO', 'minecraft:enchanted_book', 100, 120, 14, 0, 7, 0, 'frx:carta_final', 0, 25, true, 'NIVEL', CURRENT_TIMESTAMP)
